mapper.select:
SELECT
,concat(sd.dept_name, ' ', su.nick_name) createInfo
FROM car_except_record t
left join sys_user su on su.user_id = t.create_by
left join sys_dept sd on t.eps_id = sd.dept_id
WHERE t.del_flag = '0'
 and t.id = #{id}
 and t.car_id = #{carId}
 and t.car_no = #{carNo}
 and t.car_type = #{carType}
 and t.car_vehicle = #{carVehicle}
 and t.car_num = #{carNum}
 and t.pass_type = #{passType}
 and t.in_station_id = #{inStationId}
 and t.in_station like concat('%', #{inStation}, '%')
 and t.in_time = #{inTime}
 and t.out_station_id = #{outStationId}
 and t.out_station like concat('%', #{outStation}, '%')
 and t.out_time = #{outTime}
 and t.total_amount = #{totalAmount}
 and t.charge_amount = #{chargeAmount}
 and t.dif_amount = #{difAmount}
 and t.escaped_type = #{escapedType}
 and t.back_col1 = #{backCol1}
 and t.back_col2 = #{backCol2}
 and t.status = #{status}
 and t.sort = #{sort}
 and t.eps_id = #{epsId}
 and t.tenant_id = #{tenantId}
 and t.create_by = #{createBy}

and t.in_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d %H:%i:%s')
and t.out_time <= STR_TO_DATE(#{applyTime2},'%Y-%m-%d %H:%i:%s') 


and t.out_time >= STR_TO_DATE(#{applyTime3},'%Y-%m-%d %H:%i:%s')
and t.out_time <= STR_TO_DATE(#{applyTime4},'%Y-%m-%d %H:%i:%s')

 and t.car_no like concat('%', #{carNoQuery}, '%')

 and find_in_set(t.id,#{exceptIds}) > 0 
order by t.create_time desc,t.id

select

from car_except_record t
where t.id = #{id}

select escaped_type, sum(ifnull(dif_amount, 0)) escapedAmount, count(distinct car_no) number
from car_except_record
where del_flag = '0'

    and id in  #{item} 

 and escaped_type = #{escapedType}
group by escaped_type

select c.plate_color, e.car_no, e.car_type, e.escaped_type, e.dif_amount escapedAmount, e.create_time
from car_except_record e
left join car_info c on e.car_no = c.car_no

where e.del_flag = '0'

    and e.id in  #{item} 

 and e.escaped_type = #{escapedType}

select
t.car_no,count(1) exceptNum,round(sum(t.dif_amount),2) exceptAmount,round(sum(t.total_amount),2) total_amount,round(sum(t.charge_amount),2) charge_amount
from car_except_record t
where t.del_flag = '0' and t.car_no = #{carNo}
 and t.status = #{status}
group by t.car_no

select count(1) from car_except_record t
where t.del_flag = '0'
 and t.id != #{id}
and t.out_time >=  #{inTime} 
and t.in_time <= #{outTime} 
 and t.car_no = #{carNo}
